/// The translated bytes of a file, if the language has one.
pub fn file(lang: &str, name: &str) -> Option<&'static [u8]> {
    FILES
        .iter()
        .find(|(language, file, _)| *language == lang && *file == name)
        .map(|(_, _, bytes)| *bytes)
}
